import re
p='src/controller/deployments.mjs'; s=open(p).read()
def rep(a,b,count=1):
    global s
    assert a in s, a[:70]; s=s.replace(a,b,count)
# 1. profile fixed only with a usable GPU
rep("""    async function currentProfile() {
        if (!profile) {
            let snap = null;
            try {
                snap = await snapshot();
            } catch {}
            if (!profile) {
                profile = profileOf(snap);
                log.append('controller', `hardware profile: ${profile}${snap?.gpu?.name ? ` (${snap.gpu.name})` : ''}`);
            }
        }
        return profile;
    }""","""    // The profile is fixed by the first snapshot that shows a usable GPU; a
    // transient failure (a cold nvidia-smi, a GPU not attached yet) leaves it
    // undecided, and without a usable GPU every Run is refused anyway.
    async function currentProfile() {
        if (!profile) {
            let snap = null;
            try {
                snap = await snapshot();
            } catch {}
            if (!profile && snap?.gpu?.available) {
                profile = profileOf(snap);
                log.append('controller', `hardware profile: ${profile}${snap.gpu.name ? ` (${snap.gpu.name})` : ''}`);
            }
        }
        return profile;
    }""")
# 6. findAnyModel for deleteWeights (unfiltered)
rep("""    function findModel(modelId) {
        const model = catalog().find((entry) => entry.id === modelId);
        if (!model) throw new LocalLlmError('unknown_model', `No model '${modelId}' in the catalog.`);
        return model;
    }""","""    function findModel(modelId) {
        const model = catalog().find((entry) => entry.id === modelId);
        if (!model) throw new LocalLlmError('unknown_model', `No model '${modelId}' in the catalog.`);
        return model;
    }

    // Any model's entry, whatever profiles it is offered in (Delete weights
    // must be able to free what another profile downloaded).
    function findAnyModel(modelId) {
        const model = mergeCatalog(seedCatalog, state.registry).find((entry) => entry.id === modelId);
        if (!model) throw new LocalLlmError('unknown_model', `No model '${modelId}' in the catalog.`);
        return model;
    }""")
rep("""        return queue.run(async () => {
            const model = findModel(modelId);
            const weightFormat = weightsFormat({ runnerId, format });""","""        return queue.run(async () => {
            await currentProfile();
            const model = findAnyModel(modelId);
            const weightFormat = weightsFormat({ runnerId, format });""")
# 3. new id check
rep("""    function assertNewModelId(id) {
        if (catalog().some((model) => model.id === id)) {""","""    // Against every seed and every stored entry, whatever the profile or schema:
    // a user entry never reuses a seed id or another entry's id.
    function assertNewModelId(id) {
        if (seedCatalog.some((model) => model.id === id) || state.registry.some((entry) => entry?.id === id)) {""")
# status: decide profile
rep("""    async function status({ sinceSeq = 0 } = {}) {""","""    async function status({ sinceSeq = 0 } = {}) {
        await currentProfile();""")
# 2. guard: unified keeps sampling until exit
rep("""        const tick = () => {
            if (cancelled || runner !== current) return;""","""        const tick = () => {
            // Unified: watched until the process exits, through a graceful Stop
            // or Replace too (the exit cancels the guard). Dedicated: while current.
            if (cancelled || (!unified && runner !== current)) return;""")
open(p,'w').write(s)
# queue commands: add currentProfile where missing
for fn in ['function addModel','function updateModel','function removeModel','function stop()','function cancelDownload']:
    pass
open(p,'w').write(s)
EOF
