    assert.equal(performanceCoreCount({ fsApi: fakeFs({ ...spark, '/sys/fs/cgroup/cpu.max': '400000 100000\\n' }) }), 4);
    assert.equal(performanceCoreCount({ fsApi: fakeFs({ ...spark, '/sys/fs/cgroup/cpu.max': 'max 100000\\n' }) }), 10);"""
