        { code: 'duplicate_model' });
    // Its weights can still be deleted on this host.
    const deleted = await h.controller.deleteWeights({ modelId: 'big-moe', runnerId: 'llama.cpp' });
    assert.equal(typeof deleted.freedBytes, 'number');
});
